/// Corner shape from radius.style. Views draw corners through RShape, never a bare Capsule() or RoundedRectangle.
public enum RCorner {
    /// Every corner is a squircle: continuous curvature, pills and wells included, never a circular arc meeting a straight edge.
    public static let style: RoundedCornerStyle = .continuous
}

/// Springs and curves from motion.* (design-system/principles/motion-system.md). Views use these, never a raw .spring(...).
public enum RMotion {
    /// Nodes settling after a drag or a zoom.
    public static let map: Animation = .spring(response: 0.45, dampingFraction: 0.8)
    /// A sheet arriving or being dragged.
    public static let sheet: Animation = .spring(response: 0.4, dampingFraction: 0.86)
    /// A sheet leaving after a flick or a drag past the threshold.
    public static let sheetDismiss: Animation = .spring(response: 0.32, dampingFraction: 0.9)
    /// A menu growing out of the thing you tapped: settles in about 230ms with a slight overshoot (about 3%).
    public static let popover: Animation = .spring(response: 0.3, dampingFraction: 0.74)
    /// Firm and immediate, ~1% overshoot: press release, toggles, segmented thumb, checkmarks, tab icon.
    public static let snappy: Animation = .spring(response: 0.25, dampingFraction: 0.82)
    /// Dragged through water, ~5% overshoot: tiles lagging the scroll, off-axis cards settling on appear.
    public static let settle: Animation = .spring(response: 0.45, dampingFraction: 0.7)
    /// Delight, ~10% overshoot, used rarely: knows-you-well, a goal met, first episode ready, badges.
    public static let pop: Animation = .spring(response: 0.35, dampingFraction: 0.6)
    /// Big and calm, no overshoot: large layout changes, the page behind a sheet.
    public static let gentle: Animation = .spring(response: 0.55, dampingFraction: 0.92)
    /// Things arriving.
    public static func standard(_ duration: Double) -> Animation { .timingCurve(0.16, 1, 0.3, 1, duration: duration) }
    /// Things leaving.
    public static func exit(_ duration: Double) -> Animation { .timingCurve(0.4, 0, 1, 1, duration: duration) }
    /// Symmetric in-out for non-gesture moves that start and end at rest (meter fill, progress steps).
    public static func move(_ duration: Double) -> Animation { .timingCurve(0.65, 0, 0.35, 1, duration: duration) }
}

