/// Haptics from haptic.* as SwiftUI feedback. Pair each with the visual change it lands on.
public enum RHaptic {
    /// Choosing between options.
    public static let select: SensoryFeedback = .selection
    /// Something saved or done.
    public static let confirm: SensoryFeedback = .success
    /// The first-insight moment.
    public static let reveal: SensoryFeedback = .impact(flexibility: .soft)
    /// Something needs attention.
    public static let warning: SensoryFeedback = .warning
    /// The app starts listening.
    public static let listenStart: SensoryFeedback = .impact(weight: .light)
    /// The app stops listening.
    public static let listenStop: SensoryFeedback = .impact(weight: .medium)
    /// The app hands the turn back to you.
    public static let turn: SensoryFeedback = .selection
    /// Something failed.
    public static let error: SensoryFeedback = .error
    /// Switching tabs.
    public static let tab: SensoryFeedback = .selection
    /// Recording starts.
    public static let recordStart: SensoryFeedback = .impact(weight: .medium)
    /// Recording stops.
    public static let recordStop: SensoryFeedback = .impact(weight: .light)
    /// Pull to refresh lets go.
    public static let refresh: SensoryFeedback = .impact(weight: .light)
    /// A long press opens a menu.
    public static let longPress: SensoryFeedback = .impact(weight: .medium)
    /// A primary or destructive action pressed (once, on touch down).
    public static let press: SensoryFeedback = .impact(weight: .light)
    /// Scrubbing across a chapter boundary.
    public static let chapterTick: SensoryFeedback = .selection
    /// A sheet settling at a resting height after a drag.
    public static let sheetSnap: SensoryFeedback = .impact(flexibility: .soft)
    /// Skip back 15 or forward 30.
    public static let skip: SensoryFeedback = .impact(weight: .light)
    /// Retro typing out an onboarding question: one faint tick per word (not per letter), at most ~10 a second, silent on spaces and punctuation; stops when the person starts talking. Founder, 21 Oct.
    public static let typeOn: SensoryFeedback = .impact(flexibility: .soft, intensity: 0.35)
}

/// Opacities, layers and durations (seconds).
public enum RNumber {
    /// Display type (paywall: -0.6 at 30pt).
    public static let fontTrackingDisplay: Double = -0.02
    /// Text headlines.
    public static let fontTrackingTight: Double = -0.01
    /// Body.
    public static let fontTrackingNone: Double = 0
    /// Mono labels.
    public static let fontTrackingLabel: Double = 0.01
    /// 64pt and up: tight, the word reads as one shape.
    public static let fontTrackingHero: Double = -0.04
    /// 28–40pt titles.
    public static let fontTrackingTitle: Double = -0.035
    /// 20–24pt headlines and quotes.
    public static let fontTrackingCard: Double = -0.02
    /// Artwork corner radius as a share of its size.
    public static let radiusArtworkRatio: Double = 0.2
    /// Taps and toggles.
    public static let motionDurationInstant: Double = 0.08
    /// Small state changes.
    public static let motionDurationFast: Double = 0.14
    /// Most transitions.
    public static let motionDurationBase: Double = 0.2
    /// Sheets and larger moves.
    public static let motionDurationSlow: Double = 0.28
    /// The signature reveal: the buttons slide up after the first insight.
    public static let motionDurationReveal: Double = 1.22
    /// Audio fading as a reveal begins.
    public static let motionDurationAudioFade: Double = 1.05
    /// One loading rotation.
    public static let motionDurationSpin: Double = 0.9
    /// A section opening or closing.
    public static let motionDurationExpand: Double = 0.24
    /// How long a toast stays before leaving.
    public static let motionDurationToastVisible: Double = 4
    /// One pass of the loading shimmer.
    public static let motionDurationShimmer: Double = 1.4
    /// One breath of the listening pulse.
    public static let motionDurationVoicePulse: Double = 1.2
    /// One cycle of the "thinking" dots.
    public static let motionDurationTyping: Double = 0.9
    /// A number counting to its new value.
    public static let motionDurationNumberTick: Double = 0.32
    /// The lit layer fading in on focus and out on press.
    public static let motionDurationLitFade: Double = 0.2
    /// Scale to motion.scale.press on touch down.
    public static let motionDurationPressIn: Double = 0.08
    /// Spring back to 1 on release (slower out than in, so a tap feels weighted).
    public static let motionDurationPressOut: Double = 0.24
    /// The transcript gliding to keep the spoken line in place.
    public static let motionDurationTranscriptFollow: Double = 0.42
    /// After you scroll the transcript yourself, how long before it follows the voice again (or tap "back to now").
    public static let motionDurationFollowResume: Double = 4
    /// Play becoming pause and back (the two bars and the triangle morph, never a swap).
    public static let motionDurationPlayMorph: Double = 0.18
    /// The time bubble appearing above the thumb while scrubbing.
    public static let motionDurationScrubPreview: Double = 0.12
    /// A menu closing back into its source: faster than it opened, ease-in.
    public static let motionDurationPopoverExit: Double = 0.11
    /// The tapped title dims before the menu appears, so the press registers first.
    public static let motionDurationSourceDim: Double = 0.066
    /// How long loading waits before a skeleton shows, so quick loads never flash one.
    public static let motionDurationSkeletonDelay: Double = 0.4
    /// How long a skeleton waits before "still working" appears under it.
    public static let motionDurationStillWorking: Double = 8
    /// A control while pressed.
    public static let motionScalePress: Double = 0.98
    /// Where things grow from as they appear.
    public static let motionScaleEnter: Double = 0.97
    /// The screen behind a sheet shrinks to this as the sheet rises (and back as it is dragged down).
    public static let motionScaleBehindSheet: Double = 0.94
    /// The thumb grows while you hold it, so your finger never hides it.
    public static let motionScaleScrubThumb: Double = 1.6
    /// Where a menu grows from (and shrinks back to), anchored at its source.
    public static let motionScalePopoverFrom: Double = 0.86
    /// Press scale for small controls (pills, icon buttons); large things use press (0.98).
    public static let motionScalePressSmall: Double = 0.94
    /// Delay between elements arriving in sequence.
    public static let motionStagger: Double = 0.06
    /// Points per second that count as a flick down.
    public static let motionGestureDismissVelocity: Double = 800
    /// How much a sheet resists being pulled up past its top (iOS-like).
    public static let motionGestureRubberBand: Double = 0.55
    /// One full float cycle. Never under 4s.
    public static let motionLifeFloatPeriod: Double = 5
    /// Ambient motion resumes this long after the last touch.
    public static let motionLifeResumeAfter: Double = 4
    /// Most a tile tilts, in degrees, while the list moves.
    public static let motionScrollLagMaxTilt: Double = 1.5
    /// Stagger at most this many items; the rest arrive together.
    public static let motionStaggerMax: Double = 6
    /// Tab screens: colour boost under the blur, so the edge never greys.
    public static let blurTabSaturation: Double = 1.5
    /// Player transcript, top: the sheet tint rises 0 → 100% over this fraction of the band.
    public static let blurTranscriptTopTint: Double = 0.3
    /// Player transcript, bottom: the sheet tint is solid over this fraction of the band.
    public static let blurTranscriptBottomTint: Double = 0.15
    /// The page.
    public static let layerBase: Double = 0
    /// The floating player.
    public static let layerMiniPlayer: Double = 10
    /// Sheets.
    public static let layerSheet: Double = 20
    /// Dialogs.
    public static let layerDialog: Double = 40
    /// Menus and popovers.
    public static let layerPopover: Double = 50
    /// Toasts, above everything.
    public static let layerToast: Double = 60
    /// A half-height sheet, as a share of the screen.
    public static let layoutSheetDetentMedium: Double = 0.5
    /// Widest a message may be, as a share of the screen.
    public static let layoutMessageMaxWidth: Double = 0.78
    /// Anything that cannot be used right now (when not using text.disabled).
    public static let opacityDisabled: Double = 0.4
    /// Content inside a control while pressed.
    public static let opacityPressed: Double = 0.7
    /// Things not related to what you selected (the map).
    public static let opacityDimmed: Double = 0.25
    /// A tappable title while pressed.
    public static let opacitySourcePressed: Double = 0.7
    /// Something of yours on its way: a message sending, a save in flight. Same value as opacity.pressed, different meaning.
    public static let opacityPending: Double = 0.7
    /// A guess you said isn't right: it stays readable but steps back from the thread.
    public static let opacityDeclined: Double = 0.55
    /// With Reduce Motion, skeleton bars pulse 1 → this → 1 instead of the shine.
    public static let opacitySkeletonPulseFloor: Double = 0.6
}

